}
[data-mock-app="theme-innergathering"] {
  --radius: 0.375rem;

  --background: 42 60% 96%;           
  --foreground: 226 97% 24%;          

  --card: 43 100% 99%;                
  --card-foreground: 226 97% 24%;

  --popover: 43 100% 99%;
  --popover-foreground: 226 97% 24%;


  --primary: 226 97% 24%;
  --primary-foreground: 43 100% 98%;

  --secondary: 37 49% 91%;            
  --secondary-foreground: 226 97% 24%;

  --muted: 40 45% 92%;
  --muted-foreground: 211 79% 31%;    

  --accent: 42 40% 53%;               
  --accent-foreground: 226 97% 15%;

  --gold: 42 40% 53%;
  --gold-light: 42 47% 70%;           
  --smoke: 226 97% 15%;               
  --moss: 132 7% 42%;                 
  --ember: 42 41% 40%;                

  --destructive: 4 55% 42%;
  --destructive-foreground: 43 100% 98%;

  --border: 42 40% 76%;
  --input: 42 40% 76%;
  --ring: 42 40% 53%;


  --feed-offerings: 42 40% 53%;
  --feed-blog: 226 97% 24%;


  --eac-surface-bg: hsl(var(--card));
  --eac-surface-bg-soft: hsl(var(--secondary));
  --eac-surface-fg: hsl(var(--foreground));
  --eac-surface-muted: hsl(var(--muted-foreground));
  --eac-surface-line: hsl(var(--border));
  --eac-surface-rule: hsl(var(--gold));
  --eac-surface-accent: hsl(var(--gold));
  --eac-surface-on-accent: hsl(var(--smoke));
  --eac-surface-radius: var(--radius);

  --eac-hub-rubric: hsl(var(--foreground));
  --eac-font-title: var(--site-font-heading);
  --eac-font-body: var(--site-font-body);
  --eac-kind-meeting: hsl(var(--gold));
  --eac-kind-event: hsl(var(--gold));
  --eac-kind-workshop: hsl(var(--moss));
  --eac-kind-workshop-on: hsl(var(--card));
  --eac-kind-post: hsl(var(--foreground));
  --eac-kind-post-on: hsl(var(--card));
  --eac-kind-calendar: hsl(var(--smoke));
  --eac-kind-calendar-on: hsl(var(--card));
  --eac-kind-gallery: hsl(var(--ember));
  --eac-kind-gallery-on: hsl(var(--card));
  --eac-kind-board: hsl(var(--moss));
  --eac-kind-board-on: hsl(var(--card));
  --eac-kind-compose: hsl(var(--smoke));
  --eac-kind-compose-on: hsl(var(--card));


  --eac-font-prose: "Basteleur", "Cormorant Garamond", Georgia, serif;
  --eac-color-ink: hsl(var(--foreground));
  --eac-color-ink-muted: hsl(var(--muted-foreground));
  --eac-color-border: hsl(var(--border));
  --eac-accent: hsl(var(--gold));
}
