[data-mock-app="theme-innergathering"] {
  --color-background: hsl(var(--background));
  --color-foreground: hsl(var(--foreground));
  --color-card: hsl(var(--card));
  --color-card-foreground: hsl(var(--card-foreground));
  --color-popover: hsl(var(--popover));
  --color-popover-foreground: hsl(var(--popover-foreground));
  --color-primary: hsl(var(--primary));
  --color-primary-foreground: hsl(var(--primary-foreground));
  --color-secondary: hsl(var(--secondary));
  --color-secondary-foreground: hsl(var(--secondary-foreground));
  --color-muted: hsl(var(--muted));
  --color-muted-foreground: hsl(var(--muted-foreground));
  --color-accent: hsl(var(--accent));
  --color-accent-foreground: hsl(var(--accent-foreground));
  --color-destructive: hsl(var(--destructive));
  --color-destructive-foreground: hsl(var(--destructive-foreground));
  --color-border: hsl(var(--border));
  --color-input: hsl(var(--input));
  --color-ring: hsl(var(--ring));
  --color-gold: hsl(var(--gold));
  --color-smoke: hsl(var(--smoke));


  --color-feed: var(--feed, hsl(var(--gold)));

  --font-serif: "Venture", Georgia, serif;
  --font-sans: "Basteleur", "Cormorant Garamond", Georgia, serif;
  --font-display: "Brothers", "Venture", sans-serif;


  --font-brothers: "Brothers", sans-serif;
  --font-venture: "Venture", Georgia, serif;

  --radius-sm: calc(var(--radius) - 2px);
  --radius-md: var(--radius);
  --radius-lg: calc(var(--radius) + 2px);
  --radius-xl: calc(var(--radius) + 6px);
}
[data-mock-app="theme-innergathering"] * { box-sizing: border-box; }
[data-mock-app="theme-innergathering"],
[data-mock-app="theme-innergathering"] { min-height: 640px; }
[data-mock-app="theme-innergathering"] { scroll-behavior: smooth; }
[data-mock-app="theme-innergathering"] {
  background:
    radial-gradient(circle at 12% -10%, var(--ig-a-b79a55-12), transparent 30rem),
    linear-gradient(180deg, var(--ig-c-paper) 0%, var(--ig-c-parchment) 48%, var(--ig-c-section) 100%);
  background-attachment: fixed;
  color: hsl(var(--foreground));
  font-family: var(--site-font-body);
  font-size: 17px;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
}
[data-mock-app="theme-innergathering"] h1,
[data-mock-app="theme-innergathering"] h2,
[data-mock-app="theme-innergathering"] h3,
[data-mock-app="theme-innergathering"] h4 {
  font-family: var(--site-font-heading);
  letter-spacing: 0.04em;
}
[data-mock-app="theme-innergathering"] .bg-header-footer {
  background: linear-gradient(90deg, var(--ig-c-navy-deep) 0%, var(--ig-c-navy) 54%, var(--ig-c-navy-soft) 100%);
  color: var(--ig-c-paper);
}
[data-mock-app="theme-innergathering"] .card-natural {
  border: 1px solid var(--ig-a-b79a55-55);
  border-radius: var(--radius);
  background: linear-gradient(160deg, var(--ig-c-paper) 0%, var(--ig-c-parchment) 100%);
  box-shadow: 0 2px 8px var(--ig-a-01124e-08);
  transition: transform 160ms ease, box-shadow 160ms ease;
}
[data-mock-app="theme-innergathering"] .card-natural:hover { box-shadow: 0 10px 28px -12px var(--ig-a-01124e-28); }
[data-mock-app="theme-innergathering"] .saffron-divider {
  border: 0;
  height: 2px;
  margin: 1.75rem 0;
  background: linear-gradient(90deg, transparent, var(--ig-c-gold), transparent);
}
[data-mock-app="theme-innergathering"] .prose-amrit { font-family: var(--ig-font-text); font-size: 1.08rem; line-height: 1.75; }
[data-mock-app="theme-innergathering"] .prose-amrit :where(p) { margin: 0 0 1em; }
[data-mock-app="theme-innergathering"] .prose-amrit :where(h2, h3) { font-family: var(--site-font-heading); margin: 1.6em 0 0.6em; line-height: 1.2; }
[data-mock-app="theme-innergathering"] .prose-amrit :where(ul, ol) { padding-left: 1.4em; margin: 0 0 1em; }
[data-mock-app="theme-innergathering"] .prose-amrit :where(a) { color: hsl(var(--ember)); text-decoration: underline; text-underline-offset: 3px; }
[data-mock-app="theme-innergathering"] .prose-amrit :where(blockquote) { border-left: 3px solid var(--ig-c-gold); padding-left: 1rem; color: hsl(var(--muted-foreground)); font-style: italic; }
[data-mock-app="theme-innergathering"] .prose-amrit :where(img) { max-width: 100%; border-radius: var(--radius); }
[data-mock-app="theme-innergathering"] .portal-tile {
  transition: transform 180ms ease, box-shadow 180ms ease;
  box-shadow: 0 8px 24px var(--ig-a-01124e-18);
}
[data-mock-app="theme-innergathering"] .portal-tile:hover {
  transform: translateY(-3px);
  box-shadow: 0 16px 40px var(--feed-glow, var(--ig-a-b79a55-3));
}
[data-mock-app="theme-innergathering"] .marketing-root { font-size: 16px; }
[data-mock-app="theme-innergathering"] .ig-topbar {
  position: sticky; top: 0; z-index: 40;
  background: linear-gradient(90deg, var(--ig-a-01124e-97), var(--ig-a-022278-95) 48%, var(--ig-a-063179-94)), var(--ig-c-navy-deep);
  border-bottom: 1px solid var(--ig-a-b79a55-52);
  box-shadow: 0 10px 30px var(--ig-a-01124e-24);
  backdrop-filter: blur(14px);
  color: var(--ig-c-paper);
}
[data-mock-app="theme-innergathering"] .ig-topbar-inner {
  max-width: 72rem; margin: 0 auto; padding: 0.85rem clamp(1rem, 4vw, 2rem);
  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
}
[data-mock-app="theme-innergathering"] .ig-wordmark { display: flex; flex-direction: column; line-height: 1.05; text-decoration: none; }
[data-mock-app="theme-innergathering"] .ig-wordmark-main { font-family: var(--site-font-heading); font-size: clamp(1.2rem, 3vw, 1.55rem); color: var(--ig-c-gold-light); letter-spacing: 0.1em; text-shadow: 0 0 18px var(--ig-a-c6a45a-22); }
[data-mock-app="theme-innergathering"] .ig-wordmark-sub { font-family: var(--site-font-heading); font-size: 0.62rem; letter-spacing: 0.22em; text-transform: uppercase; color: var(--ig-a-fffdf8-55); margin-top: 3px; }
[data-mock-app="theme-innergathering"] .ig-nav { display: none; align-items: center; gap: clamp(0.85rem, 2.5vw, 2rem); }
[data-mock-app="theme-innergathering"] .ig-nav-toggle { background: none; border: 0; color: var(--ig-c-gold-light); padding: 0.4rem; cursor: pointer; }
@container tp (min-width: 820px) {
[data-mock-app="theme-innergathering"] .ig-nav { display: flex; }
[data-mock-app="theme-innergathering"] .ig-nav-toggle { display: none; }
}
[data-mock-app="theme-innergathering"] .ig-nav-link {
  position: relative; font-family: var(--site-font-heading); font-size: 0.86rem; font-weight: 500;
  letter-spacing: 0.12em; text-transform: uppercase; color: var(--ig-c-paper); text-decoration: none; transition: color 0.2s ease;
}
[data-mock-app="theme-innergathering"] .ig-nav-link::after { content: ""; position: absolute; bottom: -4px; left: 0; width: 0; height: 1px; background: var(--ig-c-gold); transition: width 0.3s ease; }
[data-mock-app="theme-innergathering"] .ig-nav-link:hover,
[data-mock-app="theme-innergathering"] .ig-nav-link.is-active { color: var(--ig-c-gold-light); }
[data-mock-app="theme-innergathering"] .ig-nav-link:hover::after,
[data-mock-app="theme-innergathering"] .ig-nav-link.is-active::after { width: 100%; }
[data-mock-app="theme-innergathering"] .ig-nav-link--door { padding: 0.45rem 0.95rem; border: 1px solid var(--ig-a-b79a55-55); border-radius: 2px; background: var(--ig-a-b79a55-14); color: var(--ig-c-gold-pale); }
[data-mock-app="theme-innergathering"] .ig-nav-link--door::after { display: none; }
[data-mock-app="theme-innergathering"] .ig-nav-sheet { display: grid; gap: 0.2rem; padding: 0.5rem 1rem 1rem; border-top: 1px solid var(--ig-a-b79a55-3); }
@container tp (min-width: 820px) {
[data-mock-app="theme-innergathering"] .ig-nav-sheet { display: none; }
}
[data-mock-app="theme-innergathering"] .ig-nav-sheet a { padding: 0.7rem 0.25rem; font-family: var(--site-font-heading); letter-spacing: 0.1em; text-transform: uppercase; font-size: 0.85rem; color: var(--ig-a-fffdf8-85); text-decoration: none; border-bottom: 1px solid var(--ig-a-fffdf8-06); }
[data-mock-app="theme-innergathering"] .ig-nav-sheet a.is-door { color: var(--ig-c-gold-pale); }
[data-mock-app="theme-innergathering"] .ig-page { max-width: 64rem; margin: 0 auto; padding: clamp(2rem, 5vw, 3.5rem) 1.25rem 4rem; }
[data-mock-app="theme-innergathering"] .ig-kicker { margin: 0; font-family: var(--site-font-heading); font-size: 0.7rem; letter-spacing: 0.24em; text-transform: uppercase; color: var(--ig-c-gold-dark); }
[data-mock-app="theme-innergathering"] .ig-page h1 { margin: 0.35rem 0 0; font-family: var(--site-font-heading); font-size: clamp(2rem, 5vw, 3rem); line-height: 1.05; color: var(--ig-c-navy-deep); }
[data-mock-app="theme-innergathering"] .ig-lead { font-family: var(--ig-font-text); font-size: 1.15rem; line-height: 1.75; color: var(--ig-c-navy); max-width: 66ch; }
